def prime_num(n):
    """Return True if n is a prime number, otherwise False."""
    if isinstance(n, bool):
        return False
    if isinstance(n, float):
        if not n.is_integer():
            return False
        n = int(n)
    if not isinstance(n, int):
        return False
    if n < 2:
        return False
    if n < 4:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True


if __name__ == "__main__":
    assert prime_num(13) == True
    assert prime_num(2) == True
    assert prime_num(3) == True
    assert prime_num(1) == False
    assert prime_num(0) == False
    assert prime_num(-7) == False
    assert prime_num(4) == False
    assert prime_num(25) == False
    assert prime_num(97) == True
    assert prime_num(7919) == True
    assert prime_num(7917) == False
    print("All tests passed.")

